const { getManagedFiles, loadWorkflowContract } = require("../lib/workflow-contract");

function parseArgs(argv) {
  return {
    includeMixed: argv.includes("--include-mixed"),
    includeReleaseManaged: argv.includes("--include-release-managed"),
    json: argv.includes("--json"),
    shell: argv.includes("--shell"),
  };
}

function main() {
  const args = parseArgs(process.argv.slice(2));
  const contract = loadWorkflowContract(__dirname);
  const files = getManagedFiles(contract, {
    includeMixed: args.includeMixed,
    includeReleaseManaged: args.includeReleaseManaged,
  });

  if (args.json) {
    process.stdout.write(`${JSON.stringify(files, null, 2)}\n`);
    return;
  }

  if (args.shell) {
    process.stdout.write(`${files.join(" ")}\n`);
    return;
  }

  process.stdout.write(`${files.join("\n")}\n`);
}

main();

const fs = require('fs');
const path = require('path');
const yaml = require('yaml');
const { listSkillIds, parseFrontmatter } = require('../lib/skill-utils');
const { findProjectRoot } = require('../lib/project-root');

const ROOT = findProjectRoot(__dirname);
const SKILLS_DIR = path.join(ROOT, 'skills');
const ALLOWED_FIELDS = new Set([
  'name',
  'description',
  'risk',
  'source',
  'license',
  'compatibility',
  'metadata',
  'allowed-tools',
  'date_added',
  'category',
  'id',
]);

function isPlainObject(value) {
  return value && typeof value === 'object' && !Array.isArray(value);
}

function coerceToString(value) {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string') return value.trim();
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (Array.isArray(value)) {
    const simple = value.every(item => ['string', 'number', 'boolean'].includes(typeof item));
    return simple ? value.map(item => String(item).trim()).filter(Boolean).join(', ') : JSON.stringify(value);
  }
  if (isPlainObject(value)) {
    return JSON.stringify(value);
  }
  return String(value).trim();
}

function appendMetadata(metadata, key, value) {
  const nextValue = coerceToString(value);
  if (!nextValue) return;
  if (!metadata[key]) {
    metadata[key] = nextValue;
    return;
  }
  if (metadata[key].includes(nextValue)) return;
  metadata[key] = `${metadata[key]}, ${nextValue}`;
}

function collectAllowedTools(value, toolSet) {
  if (!value) return;
  if (typeof value === 'string') {
    value
      .split(/[\s,]+/)
      .map(token => token.trim())
      .filter(Boolean)
      .forEach(token => toolSet.add(token));
    return;
  }
  if (Array.isArray(value)) {
    value
      .map(token => String(token).trim())
      .filter(Boolean)
      .forEach(token => toolSet.add(token));
  }
}

function normalizeSkill(skillId) {
  const skillPath = path.join(SKILLS_DIR, skillId, 'SKILL.md');
  const content = fs.readFileSync(skillPath, 'utf8');
  const { data, body, hasFrontmatter } = parseFrontmatter(content);

  if (!hasFrontmatter) return false;

  let modified = false;
  const updated = { ...data };
  const metadata = isPlainObject(updated.metadata) ? { ...updated.metadata } : {};
  if (updated.metadata !== undefined && !isPlainObject(updated.metadata)) {
    appendMetadata(metadata, 'legacy_metadata', updated.metadata);
    modified = true;
  }

  const allowedTools = new Set();
  collectAllowedTools(updated['allowed-tools'], allowedTools);
  collectAllowedTools(updated.tools, allowedTools);
  collectAllowedTools(updated.tool_access, allowedTools);

  if (updated.tools !== undefined) {
    delete updated.tools;
    modified = true;
  }
  if (updated.tool_access !== undefined) {
    delete updated.tool_access;
    modified = true;
  }

  for (const key of Object.keys(updated)) {
    if (ALLOWED_FIELDS.has(key)) continue;
    if (key === 'tags') {
      appendMetadata(metadata, 'tags', updated[key]);
    } else {
      appendMetadata(metadata, key, updated[key]);
    }
    delete updated[key];
    modified = true;
  }

  if (allowedTools.size) {
    updated['allowed-tools'] = Array.from(allowedTools).join(' ');
    modified = true;
  } else if (updated['allowed-tools'] !== undefined) {
    delete updated['allowed-tools'];
    modified = true;
  }

  if (Object.keys(metadata).length) {
    updated.metadata = metadata;
    modified = true;
  } else if (updated.metadata !== undefined) {
    delete updated.metadata;
    modified = true;
  }

  if (!modified) return false;

  const ordered = {};
  const order = ['id', 'name', 'description', 'category', 'risk', 'source', 'license', 'compatibility', 'date_added', 'allowed-tools', 'metadata'];
  for (const key of order) {
    if (updated[key] !== undefined) {
      ordered[key] = updated[key];
    }
  }

  const fm = yaml.stringify(ordered).trimEnd();
  const bodyPrefix = body.length && (body.startsWith('\n') || body.startsWith('\r\n')) ? '' : '\n';
  const next = `---\n${fm}\n---${bodyPrefix}${body}`;
  fs.writeFileSync(skillPath, next);
  return true;
}

function run() {
  const skillIds = listSkillIds(SKILLS_DIR);
  let updatedCount = 0;
  for (const skillId of skillIds) {
    if (normalizeSkill(skillId)) updatedCount += 1;
  }
  console.log(`Normalized frontmatter for ${updatedCount} skills.`);
}

if (require.main === module) {
  run();
}

module.exports = { run };

#!/usr/bin/env node

const fs = require("fs");
const path = require("path");
const { spawnSync } = require("child_process");

const { findProjectRoot } = require("../lib/project-root");
const {
  extractChangelogSection,
  getManagedFiles,
  loadWorkflowContract,
} = require("../lib/workflow-contract");

function parseArgs(argv) {
  const [command, version] = argv;
  return {
    command,
    version: version || null,
  };
}

function runCommand(command, args, cwd, options = {}) {
  const result = spawnSync(command, args, {
    cwd,
    encoding: "utf8",
    stdio: options.capture ? ["ignore", "pipe", "pipe"] : "inherit",
    shell: options.shell ?? process.platform === "win32",
  });

  if (result.error) {
    throw result.error;
  }

  if (typeof result.status !== "number" || result.status !== 0) {
    const stderr = options.capture ? result.stderr.trim() : "";
    throw new Error(stderr || `${command} ${args.join(" ")} failed with status ${result.status}`);
  }

  return options.capture ? result.stdout.trim() : "";
}

function ensureOnMain(projectRoot) {
  const currentBranch = runCommand("git", ["rev-parse", "--abbrev-ref", "HEAD"], projectRoot, {
    capture: true,
  });
  if (currentBranch !== "main") {
    throw new Error(`Release workflow must run from main. Current branch: ${currentBranch}`);
  }
}

function ensureCleanWorkingTree(projectRoot, message) {
  const status = runCommand("git", ["status", "--porcelain", "--untracked-files=no"], projectRoot, {
    capture: true,
  });

  if (status) {
    throw new Error(message || "Working tree has tracked changes. Commit or stash them first.");
  }
}

function ensureTagMissing(projectRoot, tagName) {
  const result = spawnSync("git", ["rev-parse", "--verify", tagName], {
    cwd: projectRoot,
    stdio: "ignore",
  });

  if (result.status === 0) {
    throw new Error(`Tag ${tagName} already exists.`);
  }
}

function ensureTagExists(projectRoot, tagName) {
  const result = spawnSync("git", ["rev-parse", "--verify", tagName], {
    cwd: projectRoot,
    stdio: "ignore",
  });

  if (result.status !== 0) {
    throw new Error(`Tag ${tagName} does not exist. Run release:prepare first.`);
  }
}

function ensureGithubReleaseMissing(projectRoot, tagName) {
  const result = spawnSync("gh", ["release", "view", tagName], {
    cwd: projectRoot,
    stdio: "ignore",
  });

  if (result.status === 0) {
    throw new Error(`GitHub release ${tagName} already exists.`);
  }
}

function readPackageVersion(projectRoot) {
  const packagePath = path.join(projectRoot, "package.json");
  const packageJson = JSON.parse(fs.readFileSync(packagePath, "utf8"));
  return packageJson.version;
}

function ensureChangelogSection(projectRoot, version) {
  const changelogPath = path.join(projectRoot, "CHANGELOG.md");
  const changelogContent = fs.readFileSync(changelogPath, "utf8");
  return extractChangelogSection(changelogContent, version);
}

function writeReleaseNotes(projectRoot, version, sectionContent) {
  const releaseNotesDir = path.join(projectRoot, ".tmp", "releases");
  const notesPath = path.join(releaseNotesDir, `v${version}.md`);
  fs.mkdirSync(releaseNotesDir, { recursive: true });
  fs.writeFileSync(notesPath, sectionContent, "utf8");
  return notesPath;
}

function runReleaseSuite(projectRoot) {
  runCommand("npm", ["run", "validate:references"], projectRoot);
  runCommand("npm", ["run", "sync:release-state"], projectRoot);
  runCommand("npm", ["run", "test"], projectRoot);
  runCommand("npm", ["run", "app:build"], projectRoot);
  runCommand("npm", ["pack", "--dry-run", "--json"], projectRoot);
}

function runReleasePreflight(projectRoot) {
  ensureOnMain(projectRoot);
  ensureCleanWorkingTree(projectRoot, "release:preflight requires a clean tracked working tree.");
  const version = readPackageVersion(projectRoot);
  ensureChangelogSection(projectRoot, version);
  runReleaseSuite(projectRoot);
  ensureCleanWorkingTree(
    projectRoot,
    "release:preflight left tracked changes. Sync and commit them before releasing.",
  );
  console.log(`[release] Preflight passed for version ${version}.`);
}

function stageReleaseFiles(projectRoot, contract) {
  const filesToStage = getManagedFiles(contract, {
    includeMixed: true,
    includeReleaseManaged: true,
  });
  runCommand("git", ["add", ...filesToStage], projectRoot);
}

function prepareRelease(projectRoot, version) {
  if (!version) {
    throw new Error("Usage: npm run release:prepare -- X.Y.Z");
  }

  ensureOnMain(projectRoot);
  ensureCleanWorkingTree(projectRoot, "release:prepare requires a clean tracked working tree.");
  ensureTagMissing(projectRoot, `v${version}`);
  ensureChangelogSection(projectRoot, version);

  const currentVersion = readPackageVersion(projectRoot);
  if (currentVersion !== version) {
    runCommand("npm", ["version", version, "--no-git-tag-version"], projectRoot);
  } else {
    console.log(`[release] package.json already set to ${version}; keeping current version.`);
  }

  runReleaseSuite(projectRoot);
  runCommand(
    "npm",
    ["run", "sync:metadata", "--", "--refresh-volatile"],
    projectRoot,
  );

  const refreshedReleaseNotes = ensureChangelogSection(projectRoot, version);
  const notesPath = writeReleaseNotes(projectRoot, version, refreshedReleaseNotes);
  const contract = loadWorkflowContract(projectRoot);
  stageReleaseFiles(projectRoot, contract);

  const stagedFiles = runCommand("git", ["diff", "--cached", "--name-only"], projectRoot, {
    capture: true,
  });
  if (!stagedFiles) {
    throw new Error("release:prepare did not stage any files. Nothing to commit.");
  }

  runCommand("git", ["commit", "-m", `chore: release v${version}`], projectRoot);
  runCommand("git", ["tag", `v${version}`], projectRoot);

  console.log(`[release] Prepared v${version}.`);
  console.log(`[release] Notes file: ${notesPath}`);
  console.log(`[release] Next step: npm run release:publish -- ${version}`);
}

function publishRelease(projectRoot, version) {
  if (!version) {
    throw new Error("Usage: npm run release:publish -- X.Y.Z");
  }

  ensureOnMain(projectRoot);
  ensureCleanWorkingTree(projectRoot, "release:publish requires a clean tracked working tree.");

  const packageVersion = readPackageVersion(projectRoot);
  if (packageVersion !== version) {
    throw new Error(`package.json version ${packageVersion} does not match requested release ${version}.`);
  }

  const tagName = `v${version}`;
  ensureTagExists(projectRoot, tagName);
  ensureGithubReleaseMissing(projectRoot, tagName);

  const tagCommit = runCommand("git", ["rev-list", "-n", "1", tagName], projectRoot, {
    capture: true,
  });
  const headCommit = runCommand("git", ["rev-parse", "HEAD"], projectRoot, {
    capture: true,
  });
  if (tagCommit !== headCommit) {
    throw new Error(`${tagName} does not point at HEAD. Refusing to publish.`);
  }

  const notesPath = writeReleaseNotes(projectRoot, version, ensureChangelogSection(projectRoot, version));

  runCommand("git", ["push", "origin", "main"], projectRoot);
  runCommand("git", ["push", "origin", tagName], projectRoot);
  runCommand("gh", ["release", "create", tagName, "--title", tagName, "--notes-file", notesPath], projectRoot);

  console.log(`[release] Published ${tagName}.`);
}

function main() {
  const args = parseArgs(process.argv.slice(2));
  const projectRoot = findProjectRoot(__dirname);

  if (args.command === "preflight") {
    runReleasePreflight(projectRoot);
    return;
  }

  if (args.command === "prepare") {
    prepareRelease(projectRoot, args.version);
    return;
  }

  if (args.command === "publish") {
    publishRelease(projectRoot, args.version);
    return;
  }

  throw new Error(
    "Usage: node tools/scripts/release_workflow.js <preflight|prepare|publish> [X.Y.Z]",
  );
}

try {
  main();
} catch (error) {
  console.error(`[release] ${error.message}`);
  process.exit(1);
}

#!/usr/bin/env node

'use strict';

const { spawn, spawnSync } = require('node:child_process');

const args = process.argv.slice(2);

if (args.length === 0) {
  console.error('Usage: node tools/scripts/run-python.js <script.py> [args...]');
  process.exit(1);
}

function uniqueCandidates(candidates) {
  const seen = new Set();
  const unique = [];

  for (const candidate of candidates) {
    const key = candidate.join('\u0000');
    if (!seen.has(key)) {
      seen.add(key);
      unique.push(candidate);
    }
  }

  return unique;
}

function getPythonCandidates() {
  // Optional override for CI/local pinning without editing scripts.
  const configuredPython =
    process.env.ANTIGRAVITY_PYTHON || process.env.npm_config_python;
  const candidates = [
    configuredPython ? [configuredPython] : null,
    // Keep this ordered list easy to update if project requirements change.
    ['python3'],
    ['python'],
    ['py', '-3'],
  ].filter(Boolean);

  return uniqueCandidates(candidates);
}

function canRun(candidate) {
  const [command, ...baseArgs] = candidate;
  const probe = spawnSync(
    command,
    [...baseArgs, '-c', 'import sys; raise SystemExit(0 if sys.version_info[0] == 3 else 1)'],
    {
      stdio: 'ignore',
      shell: false,
    },
  );

  return probe.error == null && probe.status === 0;
}

const pythonCandidates = getPythonCandidates();
const selected = pythonCandidates.find(canRun);

if (!selected) {
  console.error(
    'Unable to find a Python 3 interpreter. Tried: python3, python, py -3',
  );
  process.exit(1);
}

const [command, ...baseArgs] = selected;
const child = spawn(command, [...baseArgs, ...args], {
  stdio: 'inherit',
  shell: false,
});

child.on('error', (error) => {
  console.error(`Failed to start Python interpreter "${command}": ${error.message}`);
  process.exit(1);
});

child.on('exit', (code, signal) => {
  if (signal) {
    try {
      process.kill(process.pid, signal);
    } catch {
      process.exit(1);
    }
    return;
  }

  process.exit(code ?? 1);
});

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { createRequire } from 'module';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const require = createRequire(import.meta.url);
const { findProjectRoot } = require('../lib/project-root');
const { resolveSafeRealPath } = require('../lib/symlink-safety');

const ROOT_DIR = findProjectRoot(__dirname);
const WEB_APP_PUBLIC = path.join(ROOT_DIR, 'apps', 'web-app', 'public');

// 2. Copy skills directory content
// Note: Symlinking is better, but Windows often requires admin for symlinks. 
// We will try to copy for reliability in this environment.
function copyFolderSync(from, to, rootDir = from) {
    if (!fs.existsSync(to)) fs.mkdirSync(to, { recursive: true });

    fs.readdirSync(from).forEach(element => {
        const srcPath = path.join(from, element);
        const destPath = path.join(to, element);
        const stat = fs.lstatSync(srcPath);
        const realPath = stat.isSymbolicLink() ? resolveSafeRealPath(rootDir, srcPath) : srcPath;

        if (!realPath) {
            console.warn(`[app:setup] Skipping symlink outside skills root: ${srcPath}`);
            return;
        }

        const realStat = fs.statSync(realPath);

        if (realStat.isFile()) {
            fs.copyFileSync(realPath, destPath);
        } else if (realStat.isDirectory()) {
            copyFolderSync(realPath, destPath, rootDir);
        }
        // Skip other types (e.g. sockets, FIFOs)
    });
}

function copyIndexFiles(sourceIndex, destIndex, destBackupIndex) {
    console.log(`Copying ${sourceIndex} -> ${destIndex}...`);
    fs.copyFileSync(sourceIndex, destIndex);

    console.log(`Copying ${sourceIndex} -> ${destBackupIndex}...`);
    fs.copyFileSync(sourceIndex, destBackupIndex);
}

function main() {
    if (!fs.existsSync(WEB_APP_PUBLIC)) {
        fs.mkdirSync(WEB_APP_PUBLIC, { recursive: true });
    }

    const sourceIndex = path.join(ROOT_DIR, 'skills_index.json');
    const destIndex = path.join(WEB_APP_PUBLIC, 'skills.json');
    const destBackupIndex = path.join(WEB_APP_PUBLIC, 'skills.json.backup');
    copyIndexFiles(sourceIndex, destIndex, destBackupIndex);

    const sourceSkills = path.join(ROOT_DIR, 'skills');
    const destSkills = path.join(WEB_APP_PUBLIC, 'skills');

    console.log(`Copying skills directory...`);

    // Check if destination exists and remove it to ensure fresh copy
    if (fs.existsSync(destSkills)) {
        fs.rmSync(destSkills, { recursive: true, force: true });
    }

    copyFolderSync(sourceSkills, destSkills, sourceSkills);

    console.log('✅ Web app assets setup complete!');
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
    main();
}

export { copyFolderSync, copyIndexFiles, main };

